// ============================================================
// POSTER GENERATOR v9 — Title (large) + Full quote (small)
// Pure JS, zero require(), ~350ms, 540x540 PNG
// ============================================================

function buildPNG(W,H,imgData){
  function crc32(buf){const t=new Uint32Array(256);for(let i=0;i<256;i++){let c=i;for(let j=0;j<8;j++)c=(c&1)?0xEDB88320^(c>>>1):c>>>1;t[i]=c;}let crc=0xFFFFFFFF;for(const b of buf)crc=t[(crc^b)&0xFF]^(crc>>>8);return(crc^0xFFFFFFFF)>>>0;}
  function adler32(d){let s1=1,s2=0;for(const b of d){s1=(s1+b)%65521;s2=(s2+s1)%65521;}return(s2<<16)|s1;}
  const raw=new Uint8Array(H*(1+W*4));
  for(let y=0;y<H;y++){raw[y*(1+W*4)]=0;raw.set(imgData.subarray(y*W*4,(y+1)*W*4),y*(1+W*4)+1);}
  function deflate(data){const B=65535,o=[0x78,0x01];let p=0;while(p<data.length){const c=data.slice(p,p+B),l=(p+B>=data.length)?1:0;o.push(l,c.length&0xFF,(c.length>>8)&0xFF,~c.length&0xFF,(~c.length>>8)&0xFF);for(const b of c)o.push(b);p+=B;}const a=adler32(data);o.push((a>>24)&0xFF,(a>>16)&0xFF,(a>>8)&0xFF,a&0xFF);return o;}
  function ck(tp,d){const t=tp.split('').map(c=>c.charCodeAt(0)),crc=crc32([...t,...d]);return[(d.length>>24)&0xFF,(d.length>>16)&0xFF,(d.length>>8)&0xFF,d.length&0xFF,...t,...d,(crc>>24)&0xFF,(crc>>16)&0xFF,(crc>>8)&0xFF,crc&0xFF];}
  const IH=[(W>>24)&0xFF,(W>>16)&0xFF,(W>>8)&0xFF,W&0xFF,(H>>24)&0xFF,(H>>16)&0xFF,(H>>8)&0xFF,H&0xFF,8,6,0,0,0];
  return Buffer.from([137,80,78,71,13,10,26,10,...ck('IHDR',IH),...ck('IDAT',deflate(raw)),...ck('IEND',[])]);
}

const FR={
  ' ':[0,0,0,0,0,0,0],
  'A':[0b01110,0b10001,0b10001,0b11111,0b10001,0b10001,0b10001],
  'B':[0b11110,0b10001,0b10001,0b11110,0b10001,0b10001,0b11110],
  'C':[0b01111,0b10000,0b10000,0b10000,0b10000,0b10000,0b01111],
  'D':[0b11110,0b10001,0b10001,0b10001,0b10001,0b10001,0b11110],
  'E':[0b11111,0b10000,0b10000,0b11110,0b10000,0b10000,0b11111],
  'F':[0b11111,0b10000,0b10000,0b11110,0b10000,0b10000,0b10000],
  'G':[0b01111,0b10000,0b10000,0b10111,0b10001,0b10001,0b01111],
  'H':[0b10001,0b10001,0b10001,0b11111,0b10001,0b10001,0b10001],
  'I':[0b11111,0b00100,0b00100,0b00100,0b00100,0b00100,0b11111],
  'J':[0b11111,0b00010,0b00010,0b00010,0b00010,0b10010,0b01100],
  'K':[0b10001,0b10010,0b10100,0b11000,0b10100,0b10010,0b10001],
  'L':[0b10000,0b10000,0b10000,0b10000,0b10000,0b10000,0b11111],
  'M':[0b10001,0b11011,0b10101,0b10001,0b10001,0b10001,0b10001],
  'N':[0b10001,0b11001,0b10101,0b10011,0b10001,0b10001,0b10001],
  'O':[0b01110,0b10001,0b10001,0b10001,0b10001,0b10001,0b01110],
  'P':[0b11110,0b10001,0b10001,0b11110,0b10000,0b10000,0b10000],
  'Q':[0b01110,0b10001,0b10001,0b10001,0b10101,0b10010,0b01101],
  'R':[0b11110,0b10001,0b10001,0b11110,0b10100,0b10010,0b10001],
  'S':[0b01111,0b10000,0b10000,0b01110,0b00001,0b00001,0b11110],
  'T':[0b11111,0b00100,0b00100,0b00100,0b00100,0b00100,0b00100],
  'U':[0b10001,0b10001,0b10001,0b10001,0b10001,0b10001,0b01110],
  'V':[0b10001,0b10001,0b10001,0b10001,0b10001,0b01010,0b00100],
  'W':[0b10001,0b10001,0b10001,0b10101,0b10101,0b11011,0b10001],
  'X':[0b10001,0b01010,0b00100,0b00100,0b00100,0b01010,0b10001],
  'Y':[0b10001,0b10001,0b01010,0b00100,0b00100,0b00100,0b00100],
  'Z':[0b11111,0b00001,0b00010,0b00100,0b01000,0b10000,0b11111],
  ',':[0b00000,0b00000,0b00000,0b00000,0b01100,0b00100,0b01000],
  '.':[0b00000,0b00000,0b00000,0b00000,0b00000,0b01100,0b01100],
  '!':[0b00100,0b00100,0b00100,0b00100,0b00000,0b00000,0b00100],
  '?':[0b01110,0b10001,0b00001,0b00110,0b00100,0b00000,0b00100],
  '-':[0b00000,0b00000,0b00000,0b11111,0b00000,0b00000,0b00000],
  "'":[0b01100,0b01100,0b00100,0b01000,0b00000,0b00000,0b00000],
  ':':[0b00000,0b01100,0b01100,0b00000,0b01100,0b01100,0b00000],
  ';':[0b00000,0b01100,0b01100,0b00000,0b01100,0b00100,0b01000],
};

function sp(img,W,H,x,y,r,g,b,a){if(x<0||x>=W||y<0||y>=H)return;const i=(y*W+x)*4;img[i]=r;img[i+1]=g;img[i+2]=b;img[i+3]=a;}

function drawChar(img,W,H,ch,ox,oy,sc,r,g,b,sa=0){
  const rows=FR[ch.toUpperCase()]||FR[' '];
  for(let ri=0;ri<7;ri++)for(let ci=0;ci<5;ci++)if((rows[ri]>>(4-ci))&1){
    if(sa>0)for(let sy=0;sy<sc;sy++)for(let sx=0;sx<sc;sx++)sp(img,W,H,ox+ci*sc+sx+1,oy+ri*sc+sy+1,0,0,0,sa);
    for(let sy=0;sy<sc;sy++)for(let sx=0;sx<sc;sx++)sp(img,W,H,ox+ci*sc+sx,oy+ri*sc+sy,r,g,b,255);
  }
}

function cw(sc){return(5+1)*sc;}
function tw(text,sc){return text.length*cw(sc);}

function drawCentered(img,W,H,text,oy,sc,r,g,b,sa=0){
  let x=Math.floor((W-tw(text,sc))/2);
  for(const ch of text){drawChar(img,W,H,ch,x,oy,sc,r,g,b,sa);x+=cw(sc);}
}

function wrapText(text,maxChars){
  const words=text.split(' '),lines=[];let cur='';
  for(const w of words){const t=cur?cur+' '+w:w;if(t.length>maxChars&&cur){lines.push(cur);cur=w;}else cur=t;}
  if(cur)lines.push(cur);
  return lines;
}

// ── Main ──────────────────────────────────────────────────────
const imageText = $input.first().json.imageText;
const caption   = $input.first().json.caption;
const fileName  = $input.first().json.fileName;

// Strip hashtags — only keep the quote sentence
const rawCaption = caption.split('\n\n')[0].trim();

const W=540,H=540;
const img=new Uint8Array(W*H*4);

// Background
for(let y=0;y<H;y++){
  const v=24+Math.round((y/H)*16);
  for(let x=0;x<W;x++){const i=(y*W+x)*4;img[i]=v;img[i+1]=v;img[i+2]=v;img[i+3]=255;}
}

// Subtle diagonal texture
for(let d=0;d<W+H;d+=28){
  for(let t=0;t<W+H;t++){
    const x=d-t+H,y=t;
    if(x>=0&&x<W&&y>=0&&y<H){const i=(y*W+x)*4;img[i]=Math.min(255,img[i]+4);img[i+1]=Math.min(255,img[i+1]+4);img[i+2]=Math.min(255,img[i+2]+4);}
  }
}

// Top + bottom accent lines
for(let x=40;x<W-40;x++){sp(img,W,H,x,30,255,255,255,35);sp(img,W,H,x,31,255,255,255,15);}
for(let x=40;x<W-40;x++){sp(img,W,H,x,H-31,255,255,255,15);sp(img,W,H,x,H-30,255,255,255,35);}

// ── TITLE: auto-scale, max 3 lines, max 40% of height ────────
const titleWords=imageText.split(' ');
let tSc=8,tLines=[imageText];
for(let s=8;s>=4;s--){
  const mW=Math.floor(W*0.82),ls=[];let c='';
  for(const w of titleWords){const t=c?c+' '+w:w;if(tw(t,s)>mW&&c){ls.push(c);c=w;}else c=t;}
  if(c)ls.push(c);
  if(ls.length<=3&&ls.length*(7+3)*s<=Math.floor(H*0.40)){tSc=s;tLines=ls;break;}
}
const tLineH=(7+3)*tSc, tTotalH=tLines.length*tLineH;

// ── QUOTE: scale 2, wrap to 84% width ────────────────────────
const qSc=2, qLineH=(7+3)*qSc;
const qMaxChars=Math.floor((W*0.84)/cw(qSc));
const qLines=wrapText(rawCaption,qMaxChars);
const qTotalH=qLines.length*qLineH;

// ── Center everything vertically ─────────────────────────────
const divH=1, gap=18;
const totalH=tTotalH+gap+divH+gap+qTotalH;
const startY=Math.floor((H-totalH)/2);

const titleY=startY;
const divY=startY+tTotalH+gap;
const quoteY=divY+divH+gap;

// Draw title
for(let li=0;li<tLines.length;li++)
  drawCentered(img,W,H,tLines[li],titleY+li*tLineH,tSc,255,255,255,160);

// Divider
for(let x=Math.floor(W*0.12);x<Math.floor(W*0.88);x++)
  sp(img,W,H,x,divY,255,255,255,45);

// Draw quote (slightly dimmer for visual hierarchy)
for(let li=0;li<qLines.length;li++)
  drawCentered(img,W,H,qLines[li],quoteY+li*qLineH,qSc,205,205,205,0);

// v2s watermark
const wmSc=2,wmText='v2s',wmW=tw(wmText,wmSc);
let wx=W-wmW-18,wy=H-18-(7*wmSc);
for(const ch of wmText){drawChar(img,W,H,ch,wx,wy,wmSc,255,255,255,50);wx+=cw(wmSc);}

// ── Encode ────────────────────────────────────────────────────
const pngBuf=buildPNG(W,H,img);
const base64=pngBuf.toString('base64');

return [{
  json:{imageText,caption,fileName},
  binary:{data:{data:base64,mimeType:'image/png',fileType:'image',fileName,fileExtension:'png'}}
}];

// Image is already validated and named by Generate Poster Image node
// Just pass through and confirm binary exists
const item = $input.first();

if (!item.binary || !item.binary.data) {
  throw new Error('NO BINARY DATA: Poster generation failed. Check the Generate Poster Image node logs.');
}

// Confirm metadata
item.binary.data.fileName = $('Daily Quote Engine').first().json.fileName;
item.binary.data.fileExtension = 'png';
item.binary.data.mimeType = 'image/png';

return [item];

